// Courtyard expansion, world-space clues, and a stencil-clipped planar mirror.
rooms.garden='The courtyard';rooms.shed='The garden shed';spawn.garden=[0,-2,Math.PI];spawn.shed=[-6,-7,0];
const mirrorPlane=2.248;
const noteDefs=[{id:'note1',p:[1.38,1.45,3.8],axis:'x',title:'BEFORE YOU LEAVE',text:'The gate knows three words.\nFirst: WE.\nDo not knock back.'},{id:'note2',p:[-6.13,1.05,8.5],axis:'x',title:'DON’T FEED IT',text:'Second: WERE.\nThe sandwiches appear because\nsomeone keeps setting your place.'},{id:'note3',p:[2.8,1.65,17.87],axis:'z',title:'COUNT THE CHAIRS',text:'Third: HERE.\nSay all three at the garden gate.\nTake nobody’s reflection with you.'},{id:'note4',p:[-5.8,1.5,-8.87],axis:'z',title:'THE GARDENER',text:'Turn the music box in the shed.\nTake its lullaby to the well.\nDo not look down while it sings.'},{id:'note5',p:[8.88,1.4,-7],axis:'x',title:'PLEASE REMEMBER',text:'If every note is found,\nwrite your own name in the diary.\nYou are allowed to be whole.'},{id:'note6',p:[4.2,.45,2.12],axis:'z',title:'UNDER THE MIRROR',text:'The glass remembers the room.\nSometimes it remembers someone\nwho is no longer standing there.'}];
function noteState(){return s.notes||(s.notes=[])}
function readNote(id){let n=noteDefs.find(n=>n.id===id);if(!n)return;let first=!noteState().includes(id);if(first)noteState().push(id);save();modal(n.title,n.text,[['Put the note back',close]]);if(first)queueSanity(4)}
function newEndingAllowed(id){let n=noteState();return id==='gate'?['note1','note2','note3'].every(x=>n.includes(x))&&flags().gateWords:id==='well'?n.includes('note4')&&flags().music&&flags().wellQuiet:id==='whole'?n.length===6&&flags().truth&&flags().mirror:false}
const extendedEnding=ending;ending=function(id){let values={gate:['Ending VII · We were here','You speak the three words. The gate opens onto a morning that has not happened yet.\nThe house calls after you in Mother’s voice. This time, you do not answer.'],well:['Ending VIII · The lullaby below','The music box sings into the well. A child finishes the song from somewhere far beneath the water.\nWhen you return to the house, the spare room is a cupboard.\nEvery night, a new flower grows beside the well.'],whole:['Ending IX · Your own handwriting','You write your own name over both names in the diary.\nThe mirror cracks without breaking. Mother remembers a single child, with every memory intact.\nThe sticky notes disappear. You leave one of your own: “We got out.”']};if(!values[id])return extendedEnding(id);if(!newEndingAllowed(id))return;s.ending={title:values[id][0],body:values[id][1]};save();showEnding()};
const sixFinale=finale;finale=function(){if(!s.read){diary();return}let unlocked=['gate','well','whole'].filter(newEndingAllowed);if(!unlocked.length)return sixFinale();modal('The house offers another way','Your notes have revealed paths the room never mentioned.',[['The original six paths',sixFinale],...unlocked.map(id=>[({gate:'Leave through the garden gate',well:'Let the well keep the memory',whole:'Write your own name'})[id],()=>ending(id)]),['Keep exploring',close]])};
function gardenAction(id){if(id==='gate')modal('The garden gate','Three shallow scratches wait for three words. The sticky notes inside the house may help.',[['Speak “WE WERE HERE”',()=>{if(!['note1','note2','note3'].every(x=>noteState().includes(x)))return modal('A borrowed voice','The gate does not believe you. Find the three notes first.',[['Step back',close]]);discovery('gateWords','The latch releases','A warm wind blows through a gap that was not there before. The final diary entry will let you choose this way out.')}],['Step back',close]]);if(id==='music')discovery('music','The music box','You wind the handle. A lullaby plays backwards, then forwards. A tiny brass boat turns in the centre.');if(id==='well'){if(!flags().music||!noteState().includes('note4'))return modal('The old well','From below: “You forgot the song.” There is a note in the shed.',[['Step away',close]]);discovery('wellQuiet','A song for the well','You play the music box into the darkness. The water stops reflecting the sky. Your new path waits in the final diary entry.')}}
const gardenTargets=targets;targets=function(){return gardenTargets().concat(noteDefs.map(n=>({name:'Sticky note: '+n.id,p:n.p,fn:()=>readNote(n.id)})),[{name:'Garden gate',p:[0,1.2,-10],fn:()=>gardenAction('gate')},{name:'Music box',p:[-6,.9,-7.8],fn:()=>gardenAction('music')},{name:'Old well',p:[4,.8,-6],fn:()=>gardenAction('well')}])};
function quadAt(p,w,h,axis){let [x,y,z]=p;return axis==='x'?[[x,y-h/2,z-w/2],[x,y-h/2,z+w/2],[x,y+h/2,z+w/2],[x,y+h/2,z-w/2]]:[[x-w/2,y-h/2,z],[x+w/2,y-h/2,z],[x+w/2,y+h/2,z],[x-w/2,y+h/2,z]]}
const gardenSurface=surface;surface=function(t){if(t.name.startsWith('Sticky note: ')){let n=noteDefs.find(n=>t.name.endsWith(n.id));return quadAt(n.p,.32,.32,n.axis)}if(t.name==='Covered mirror')return quadAt([4.2,1.52,mirrorPlane],1.02,1.56,'z');if(t.name==='Garden gate')return quadAt(t.p,1.7,2.3,'z');if(t.name==='Music box')return quadAt(t.p,.45,.2,'z');if(t.name==='Old well')return quadAt(t.p,1.2,.65,'z');return gardenSurface(t)};
const gardenBuild=buildHouse;buildHouse=function(){gardenBuild();box(0,-.08,-5.5,18,.08,11,'#3b4a32');box(0,.005,-5,1.4,.015,10,'#756e58');for(let x of [-9,9])wall(x,-5.5,.18,11,'#394737');wall(-5,-11,8,.18,'#394737');wall(5,-11,8,.18,'#394737');for(let x=-8.5;x<9;x+=.45)box(x,0,-10.8,.12,1.8,.12,'#3e4837');box(0,0,-10,1.8,2.2,.13,'#536349',true);for(let z=-9;z<0;z+=.8)box(-8.8,0,z,.12,1.9,.12,'#48533d');
// Shed with an open, walkable doorway.
box(-6,-.03,-7,4,.04,4,'#645741');wall(-8,-7,.14,4,'#605944');wall(-4,-7,.14,4,'#605944');wall(-6,-9,4,.14,'#605944');wall(-7.4,-5,1.2,.14,'#605944');wall(-4.6,-5,1.2,.14,'#605944');box(-6,2.35,-5,1.6,.45,.14,'#605944');box(-6,2.8,-7,4.2,.16,4.2,'#3b3e2d');table(-6,-7.8,1.4,.6);box(-6,.82,-7.8,.45,.22,.3,'#83633b');for(let y of [.35,1,1.65])box(-7.45,y,-7,1,.06,2.8,'#61513a');for(let z of [-6.2,-7,-7.8])box(-7.45,1.07,z,.45,.3,.4,'#7b7455');
// Stone well, bench and crooked garden markers.
for(let x of [3.4,4.6])box(x,0,-6,.18,.9,1.4,'#7a7a66',true);for(let z of [-6.6,-5.4])box(4,0,z,1.4,.9,.18,'#7a7a66',true);box(4,.1,-6,1,.02,1,'#101b15');box(6,.4,-3,1.8,.15,.55,'#61543d',true);legs(6,-3,1.7,.5);for(let i=0;i<8;i++){box(7.6,0,-1-i*.7,.07,1.1,.07,'#483e2e');box(7.6,.75,-1-i*.7,.6,.08,.07,'#483e2e')}for(let n of noteDefs){let [x,y,z]=n.p;box(x,y-.16,z,n.axis==='x'?.012:.32,.32,n.axis==='x'?.32:.012,'#d9c77b')}
// Mounting chain and a cracked frame on the bedroom wall.
box(4.2,2.4,2.14,.025,.16,.025,'#938570');box(3.64,.65,2.25,.065,1.75,.06,'#b09a66');box(4.76,.65,2.25,.065,1.75,.06,'#b09a66');
};
const gardenMap=showMap;showMap=function(){modal('The house and grounds','The courtyard is through the front entrance at the beginning of the hallway. The shed and well hide more clues.',Object.entries(rooms).map(([id,name])=>[name,()=>{if(id==='kitchen'||id==='bedroom'||id==='spare')house.doors[id]=true;[house.x,house.z,house.a]=spawn[id];house.jumpHeight=0;s.room=id;save();close()}]).concat([['Back',close]]))};
const gardenTasks=taskRows;taskRows=function(){return gardenTasks().concat([{label:'Explore: find six hidden sticky notes ('+noteState().length+'/6)',done:noteState().length===6}],noteState().includes('note4')?[{label:'Explore: play the music box into the well',done:!!flags().wellQuiet}]:[])};
const gardenClose=close;close=function(){gardenClose();if(s.room==='garden')say('The courtyard is silent. A gate, an old well, and the shed wait in the dark.');if(s.room==='shed')say('The shed smells of rain. A little music box waits beside a yellow note.');};
const noteReset=reset;reset=function(){noteReset();s.notes=[];save()};
function reflectedFaces(){let data=[];for(let f of house.faces){let polygon=[];for(let i=0;i<4;i++){let a=f.v[i],b=f.v[(i+1)%4],inside=a[2]>mirrorPlane+.02,next=b[2]>mirrorPlane+.02;if(inside)polygon.push(a);if(inside!==next){let t=(mirrorPlane+.02-a[2])/(b[2]-a[2]);polygon.push(a.map((n,j)=>n+(b[j]-n)*t))}}for(let i=1;i<polygon.length-1;i++)for(let p of [polygon[0],polygon[i],polygon[i+1]])data.push(p[0],p[1],2*mirrorPlane-p[2],...f.rgb.map(n=>Math.min(1,n*f.shade*.86/255)))}return new Float32Array(data)}
function renderMirror(){if(!gpu||!flags().mirror||house.z<=mirrorPlane||house.x<1.5||house.x>7.5)return;const gl=gpu.gl;if(!gl.getContextAttributes?.().stencil)return;
if(gpu.mirrorVersion!==house.meshVersion){gpu.reflectionBuffer??=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,gpu.reflectionBuffer);let data=reflectedFaces();gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);gpu.reflectionCount=data.length/6;gpu.maskBuffer??=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,gpu.maskBuffer);let q=quadAt([4.2,1.52,mirrorPlane],1.02,1.56,'z'),mask=[];for(let i of [0,1,2,0,2,3])mask.push(...q[i],.15,.2,.17);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(mask),gl.STATIC_DRAW);gpu.mirrorVersion=house.meshVersion;}
function bind(buffer){gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.vertexAttribPointer(gpu.position,3,gl.FLOAT,false,24,0);gl.vertexAttribPointer(gpu.color,3,gl.FLOAT,false,24,12)}
gl.enable(gl.STENCIL_TEST);gl.stencilMask(255);gl.clearStencil(0);gl.clear(gl.STENCIL_BUFFER_BIT);gl.stencilFunc(gl.ALWAYS,1,255);gl.stencilOp(gl.KEEP,gl.KEEP,gl.REPLACE);gl.colorMask(false,false,false,false);gl.depthMask(false);bind(gpu.maskBuffer);gl.drawArrays(gl.TRIANGLES,0,6);
gl.colorMask(true,true,true,true);gl.depthMask(true);gl.stencilMask(0);gl.stencilFunc(gl.EQUAL,1,255);gl.stencilOp(gl.KEEP,gl.KEEP,gl.KEEP);gl.clear(gl.DEPTH_BUFFER_BIT);bind(gpu.reflectionBuffer);gl.drawArrays(gl.TRIANGLES,0,gpu.reflectionCount);gl.disable(gl.STENCIL_TEST);gl.stencilMask(255);bind(gpu.buffer);
}
const decalTextures=new Map();
function textTexture(key,lines,bg){if(decalTextures.has(key))return decalTextures.get(key);let c=document.createElement('canvas');c.width=512;c.height=512;let g=c.getContext('2d');if(bg){g.fillStyle=bg;g.fillRect(0,0,512,512);g.fillStyle='#aa954c';g.fillRect(0,0,512,25)}g.fillStyle=bg?'#32372a':'#f3eedb';g.font=(bg?'bold 36':'italic 36')+'px Georgia';g.textAlign='center';lines.forEach((line,i)=>g.fillText(line,256,85+i*59));if(!bg){g.strokeStyle='#b3c1b470';g.lineWidth=3;g.beginPath();g.moveTo(475,0);g.lineTo(430,130);g.lineTo(470,200);g.lineTo(425,340);g.stroke()}decalTextures.set(key,c);return c}
function texturedTriangle(img,src,dst){let [a,b,c]=src,[p,q,r]=dst;let den=(b[0]-a[0])*(c[1]-a[1])-(c[0]-a[0])*(b[1]-a[1]);if(Math.abs(den)<.001)return;let ax=((q[0]-p[0])*(c[1]-a[1])-(r[0]-p[0])*(b[1]-a[1]))/den,bx=((r[0]-p[0])*(b[0]-a[0])-(q[0]-p[0])*(c[0]-a[0]))/den,ay=((q[1]-p[1])*(c[1]-a[1])-(r[1]-p[1])*(b[1]-a[1]))/den,by=((r[1]-p[1])*(b[0]-a[0])-(q[1]-p[1])*(c[0]-a[0]))/den;ctx.save();ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.lineTo(...r);ctx.closePath();ctx.clip();ctx.setTransform(ax,ay,bx,by,p[0]-ax*a[0]-bx*a[1],p[1]-ay*a[0]-by*a[1]);ctx.drawImage(img,0,0);ctx.restore()}
function drawDecal(img,world){let v=world.map(view);if(v.some(p=>p[2]<.12))return;let p=v.map(screen);if(p.every(a=>a[0]<0)||p.every(a=>a[0]>1000)||p.every(a=>a[1]<0)||p.every(a=>a[1]>690))return;let src=[[0,512],[512,512],[512,0],[0,0]];for(let i of [1,2])texturedTriangle(img,[src[0],src[i],src[i+1]],[p[0],p[i],p[i+1]])}
function drawDecals(){for(let n of noteDefs){let distance=Math.hypot(n.p[0]-house.x,n.p[2]-house.z);if(distance>6||!visibleTo({p:n.p}))continue;let q=quadAt(n.p,.32,.32,n.axis);if(n.axis==='x'&&n.p[0]>0||n.axis==='z'&&n.p[2]<3)q=[q[1],q[0],q[3],q[2]];drawDecal(textTexture(n.id,[n.title,...n.text.split('\n')],'#d9c77b'),q)}if(flags().mirror&&visibleTo({p:[4.2,1.52,mirrorPlane]})&&house.z>mirrorPlane&&house.x>1.5&&house.x<7.5&&Math.hypot(house.x-4.2,house.z-mirrorPlane)<7)drawDecal(textTexture('mirror-message',['Draw the mark','in my room.','I can carry','the memory away.'],null),(()=>{let q=quadAt([4.2,1.52,mirrorPlane+.003],1.02,1.56,'z');return [q[1],q[0],q[3],q[2]]})())}
function softwareMirror(){if(!flags().mirror||house.z<=mirrorPlane||house.x<1.5||house.x>7.5)return;let q=quadAt([4.2,1.52,mirrorPlane],1.02,1.56,'z').map(view);if(q.some(v=>v[2]<.1))return;ctx.save();ctx.beginPath();q.map(screen).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.clip();let data=reflectedFaces(),triangles=[];for(let i=0;i<data.length;i+=18){let v=[];for(let j=0;j<18;j+=6)v.push(view([data[i+j],data[i+j+1],data[i+j+2]]));let p=clip(v);if(p.length>=3)triangles.push({p,z:p.reduce((n,v)=>n+v[2],0)/p.length,color:'rgb('+Array.from(data.slice(i+3,i+6)).map(n=>Math.floor(n*190)).join(',')+')'})}triangles.sort((a,b)=>b.z-a.z);for(let t of triangles){ctx.fillStyle=t.color;ctx.beginPath();t.p.map(screen).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill()}ctx.restore()}
